from itertools import combinations
from typing import FrozenSet, Iterator, TypeVar
T = TypeVar("T")
def powerset(face: FrozenSet[T]) -> Iterator[FrozenSet[T]]:
    items = tuple(face)
    for r in range(len(items) + 1):
        for choice in combinations(items, r):
            yield frozenset(choice)
def main() -> None:
    witness = frozenset(range(6))
    certificate = set(powerset(witness))
    histogram = [sum(len(s) == r for s in certificate) for r in range(7)]
    assert len(certificate) == 2 ** len(witness)
    print("width:", len(witness), "faces:", len(certificate))
    print("level sizes:", histogram)
if __name__ == "__main__": main()

from itertools import combinations
from typing import FrozenSet
def powerset(s: FrozenSet[int]) -> set[FrozenSet[int]]:
    a = tuple(s)
    return {frozenset(c) for r in range(len(a)+1) for c in combinations(a,r)}
def main() -> None:
    u, v = frozenset({1,2,3,4}), frozenset({3,4,5,6})
    actual = len(powerset(u) | powerset(v))
    formula = 2**len(u) + 2**len(v) - 2**len(u & v)
    assert actual == formula
    print(f"exact union: {actual}; formula: {formula}; coarse bound: {2*2**4}")
if __name__ == "__main__": main()

