from itertools import combinations
from typing import FrozenSet, Iterable, TypeVar
T = TypeVar("T")
def generate_certificate(witnesses: Iterable[FrozenSet[T]]) -> set[FrozenSet[T]]:
    result: set[FrozenSet[T]] = set()
    for witness in witnesses:
        items = tuple(witness)
        for r in range(len(items) + 1):
            result.update(frozenset(c) for c in combinations(items, r))
    return result

from typing import FrozenSet, Iterable, TypeVar
T = TypeVar("T")
def maximal_antichain(witnesses: Iterable[FrozenSet[T]]) -> set[FrozenSet[T]]:
    family = set(witnesses)
    return {w for w in family if not any(w < v for v in family)}

from itertools import combinations
from typing import FrozenSet, Sequence, TypeVar
T = TypeVar("T")
def certificate_cardinality(witnesses: Sequence[FrozenSet[T]]) -> int:
    total = 0
    for r in range(1, len(witnesses) + 1):
        for group in combinations(witnesses, r):
            intersection = set(group[0])
            for witness in group[1:]: intersection.intersection_update(witness)
            total += (1 if r % 2 else -1) * 2 ** len(intersection)
    return total

